const pad = (n: number, len = 12) => String(n).padStart(len, "0");
export const demoProductId = (n: number) => `a0000000-0000-4000-8000-${pad(n)}`;

const slugOf = (name: string) =>
  name
    .toLowerCase()
    .replace(/[^a-z0-9]+/g, "-")
    .replace(/^-|-$/g, "");

export const DEMO_PALETTES: Record<string, DemoSeed["palette"] & { name: string; colour: string; embroidery: EmbroideryType }> =
  Object.fromEntries(
    SEEDS.map((s) => [
      slugOf(s.name),
      { ...s.palette, name: s.name, colour: s.colour, embroidery: s.embroidery },
    ]),
  );

export const DEMO_PRODUCTS: Product[] = SEEDS.map((s) => {
  const created = new Date(Date.UTC(2026, 9, 1 + s.n * 2, 9)).toISOString();
  return {
    id: demoProductId(s.n),
    name: s.name,
    slug: slugOf(s.name),
    sku: `TZ-${s.category.slice(0, 3).toUpperCase()}-${String(s.n).padStart(3, "0")}`,
    category_id: cat(s.category),
    short_description: s.short,
    description: s.description,
    fabric: s.fabric,
    embroidery_type: s.embroidery,
    pieces: s.pieces,
    colour: s.colour,
    price: s.price,
    discount_type: s.discount?.type ?? "none",
    discount_value: s.discount?.value ?? 0,
    discount_starts_at: s.discount?.starts ?? null,
    discount_ends_at: s.discount?.ends ?? null,
    is_made_to_order: Boolean(s.madeToOrder),
    lead_time_days: s.madeToOrder ?? null,
    handwork_hours: s.hours,
    allow_custom_stitching: s.category !== "unstitched",
    show_in_wardrobe: Boolean(s.wardrobe),
    wardrobe_order: s.wardrobe ?? 0,
    is_featured: Boolean(s.featured),
    is_new_arrival: Boolean(s.isNew),
    status: "published",
    seo_title: `${s.name} — Hand-embroidered ${s.colour} | Tanzaib`,
    seo_description: s.short,
    created_at: created,
    updated_at: created,
  };
});

export const DEMO_IMAGES: ProductImage[] = DEMO_PRODUCTS.flatMap((p, i) => {
  const base = `/dummy/${p.slug}`;
  const n = i + 1;
  const img = (k: number, kind: ProductImage["kind"], file: string, alt: string): ProductImage => ({
    id: `b0000000-0000-4000-8000-${pad(n * 10 + k)}`,
    product_id: p.id,
    url: `${base}/${file}`,
    kind,
    alt,
    sort_order: k,
  });
  return [
    img(0, "front", "front.svg", `${p.name} — front view, ${p.colour}`),
    img(1, "back", "back.svg", `${p.name} — back view`),
    img(2, "detail", "detail-1.svg", `${p.name} — embroidery close-up`),
    img(3, "detail", "detail-2.svg", `${p.name} — border detail`),
    img(4, "hanger", "hanger.svg", `${p.name} on a hanger`),
  ];
});

export const DEMO_VARIANTS: ProductVariant[] = SEEDS.flatMap((s) => {
  const productId = demoProductId(s.n);
  const isMto = Boolean(s.madeToOrder);
  const sizes: Size[] = s.category === "unstitched" ? ["M"] : ["XS", "S", "M", "L", "XL", "CUSTOM"];
  return sizes.map((size, k) => ({
    id: `d0000000-0000-4000-8000-${pad(s.n * 10 + k)}`,
    product_id: productId,
    size,
    stock: isMto ? 0 : (s.stock[size] ?? 0),
  }));
});

